-- Aliza Flowers: kataloq. Supabase > SQL Editor-də bir dəfə işlədin.
-- Qiyməti sonra Admin paneldən hər məhsula yazın.
begin;
alter table public.products alter column price drop not null;

-- Köhnə məhsulların boş kateqoriyaları
update public.products set category_id='roses' where category_id is null and image_url like '%product_red_roses_%';
update public.products set category_id='baskets' where category_id is null and image_url like '%product_pastel_basket%';
update public.products set category_id='bouquets' where category_id is null and (image_url like '%product_mixed_bouquet%' or image_url like '%sarigul%' or image_url like '%hesbs%');
update public.products set category_id='boxes' where category_id is null and image_url like '%product_pink_box%';

-- Yeni məhsullar (təkrar işlədilsə dublikat yaratmır)
insert into public.products (name, description, price, category_id, color, image_url, featured, active, sort_order)
select v.name, v.description, null, v.category_id, v.color, v.image_url, v.featured, true, v.sort_order
from (values
  ('{"az":"Tünd Çəhrayı Kol Qızılgül Buketi","en":"Deep Pink Spray Rose Bouquet","ru":"Букет тёмно-розовых кустовых роз"}'::jsonb, '{"az":"Kraft kağızda, çəhrayı lentli sıx kol qızılgül buketi.","en":"A dense spray rose bouquet in kraft paper with a pink ribbon.","ru":"Пышный букет кустовых роз в крафте с розовой лентой."}'::jsonb, 'roses', 'pink', '/assets/products/tund-cehrayi-kol-qizilgul-buketi-kraft-kagizda.webp', false, -100),
  ('{"az":"Böyük Çəhrayı-Ağ Qızılgül Buketi","en":"Grand Pink & White Rose Bouquet","ru":"Большой бело-розовый букет роз"}'::jsonb, '{"az":"Çəhrayının müxtəlif tonlarında və ağ qızılgüllərdən hazırlanmış həcmli buket.","en":"A generous bouquet of white roses and shades of pink.","ru":"Объёмный букет из белых роз и роз разных оттенков розового."}'::jsonb, 'roses', 'pink', '/assets/products/boyuk-cehrayi-ag-qizilgul-buketi.webp', true, -99),
  ('{"az":"Ağ Qızılgül və Evkalipt Buketi","en":"White Rose & Eucalyptus Bouquet","ru":"Букет белых роз с эвкалиптом"}'::jsonb, '{"az":"Şəffaf bükülüdə, evkalipt yarpaqları ilə zərif ağ qızılgüllər.","en":"Elegant white roses with eucalyptus in sheer wrapping.","ru":"Нежные белые розы с эвкалиптом в прозрачной упаковке."}'::jsonb, 'roses', 'white', '/assets/products/ag-qizilgul-evkalipt-buketi.webp', false, -98),
  ('{"az":"Çəhrayı Hörmə Səbət Kompozisiyası","en":"Pink Woven Basket Arrangement","ru":"Композиция в розовой плетёной корзине"}'::jsonb, '{"az":"Çəhrayı hörmə səbətdə, lentlərlə tamamlanmış çəhrayı gül kompozisiyası.","en":"Pink blooms in a pink woven basket, finished with ribbons.","ru":"Розовые цветы в розовой плетёной корзине с лентами."}'::jsonb, 'baskets', 'pink', '/assets/products/cehrayi-gul-hasir-sebet-kompozisiyasi.webp', false, -97),
  ('{"az":"Nəhəng Çəhrayı-Ağ Hortenziya Buketi","en":"Grand Pink & White Hydrangea Bouquet","ru":"Огромный букет гортензий"}'::jsonb, '{"az":"Çəhrayı və ağ hortenziyaların əsas olduğu, lentlə bəzədilmiş nəhəng buket.","en":"An oversized bouquet led by pink and white hydrangeas, trimmed with ribbon.","ru":"Огромный букет с розовыми и белыми гортензиями, украшенный лентой."}'::jsonb, 'exclusive', 'pink', '/assets/products/neheng-cehrayi-ag-hortenziya-buketi.webp', false, -96),
  ('{"az":"Böyük Ağ Kol Qızılgül Buketi","en":"Grand White Spray Rose Bouquet","ru":"Большой букет белых кустовых роз"}'::jsonb, '{"az":"Yalnız ağ kol qızılgüllərdən yığılmış, kürə formalı böyük buket.","en":"A large, globe-shaped bouquet made entirely of white spray roses.","ru":"Большой шарообразный букет только из белых кустовых роз."}'::jsonb, 'roses', 'white', '/assets/products/ag-kol-qizilgul-boyuk-buket.webp', true, -95),
  ('{"az":"Narıncı Zanbaqlı Qarışıq Buket","en":"Orange Lily Mixed Bouquet","ru":"Смешанный букет с оранжевыми лилиями"}'::jsonb, '{"az":"Narıncı zanbaq və qızılgüllərin bənövşəyi çiçəklərlə canlı birləşməsi.","en":"Orange lilies and roses in a vivid mix with purple blooms.","ru":"Оранжевые лилии и розы в яркой комбинации с фиолетовыми цветами."}'::jsonb, 'bouquets', 'orange', '/assets/products/narinci-zanbaq-qizilgul-qarisiq-buket.webp', false, -94),
  ('{"az":"Çəhrayı Kol Qızılgül Buketi","en":"Pink Spray Rose Bouquet","ru":"Букет розовых кустовых роз"}'::jsonb, '{"az":"Çəhrayı bükülüdə, eyni rəngli lentlə kol qızılgül buketi.","en":"Spray roses in pink wrapping with a matching ribbon.","ru":"Кустовые розы в розовой упаковке с лентой в тон."}'::jsonb, 'roses', 'pink', '/assets/products/cehrayi-kol-qizilgul-buketi.webp', false, -93),
  ('{"az":"Bənövşəyi Qablaşdırmada Qarışıq Buket","en":"Mixed Bouquet in Violet Wrap","ru":"Смешанный букет в фиолетовой упаковке"}'::jsonb, '{"az":"Şaftalı rəngli qızılgüllər və gipsofila ilə çoxqatlı bənövşəyi bükülüdə buket.","en":"Peach roses and gypsophila in layered violet wrapping.","ru":"Персиковые розы и гипсофила в многослойной фиолетовой упаковке."}'::jsonb, 'bouquets', 'purple', '/assets/products/benovseyi-qablasdirmada-qarisiq-qizilgul-buketi.webp', true, -92),
  ('{"az":"Günəbaxanlı Qarışıq Buket","en":"Sunflower Mixed Bouquet","ru":"Смешанный букет с подсолнухами"}'::jsonb, '{"az":"Günəbaxanların ağ və qırmızı çiçəklərlə canlı birləşməsi.","en":"Sunflowers paired with white and red blooms.","ru":"Подсолнухи в сочетании с белыми и красными цветами."}'::jsonb, 'bouquets', 'yellow', '/assets/products/gunebaxan-ag-qirmizi-qarisiq-buket.webp', false, -91),
  ('{"az":"Qəzet Bükülüdə Günəbaxan Buketi","en":"Sunflower Bouquet in Newsprint","ru":"Букет подсолнухов в газетной упаковке"}'::jsonb, '{"az":"Qəzet naxışlı kağızda, sadə və günəşli günəbaxan buketi.","en":"A simple, sunny sunflower bouquet in newsprint-style paper.","ru":"Простой солнечный букет подсолнухов в бумаге с газетным принтом."}'::jsonb, 'bouquets', 'yellow', '/assets/products/gunebaxan-buketi-qezet-qablasdirma.webp', false, -90),
  ('{"az":"Ürək Formalı Gül Kompozisiyası","en":"Heart-Shaped Flower Arrangement","ru":"Композиция в форме сердца"}'::jsonb, '{"az":"Ağ və çəhrayı çiçəklərdən ürək formasında hazırlanmış xüsusi kompozisiya.","en":"A special heart-shaped arrangement in white and pink blooms.","ru":"Особая композиция в форме сердца из белых и розовых цветов."}'::jsonb, 'exclusive', 'white', '/assets/products/urek-formali-ag-cehrayi-gul-kompozisiyasi.webp', false, -89),
  ('{"az":"Yaşıl Hortenziya və Çəhrayı Qızılgül Buketi","en":"Green Hydrangea & Pink Rose Bouquet","ru":"Букет зелёных гортензий и розовых роз"}'::jsonb, '{"az":"Yaşıl hortenziyalar üzərində çəhrayı qızılgüllər olan nəhəng eksklyuziv buket.","en":"An oversized bouquet of pink roses set over green hydrangeas.","ru":"Огромный букет: розовые розы на фоне зелёных гортензий."}'::jsonb, 'exclusive', 'pink', '/assets/products/yasil-hortenziya-cehrayi-qizilgul-eksklyuziv-buket.webp', true, -88),
  ('{"az":"Leopard Bükülüdə Kalla Buketləri","en":"Calla Lily Bouquets in Leopard Wrap","ru":"Букеты калл в леопардовой упаковке"}'::jsonb, '{"az":"Sarı, çəhrayı və tünd kallalardan leopard naxışlı bükülüdə buketlər.","en":"Yellow, pink and dark calla lilies in leopard-print wrapping.","ru":"Жёлтые, розовые и тёмные каллы в леопардовой упаковке."}'::jsonb, 'exclusive', 'all', '/assets/products/kalla-buketleri-leopard-qablasdirma.webp', false, -87),
  ('{"az":"Çəhrayı Hortenziya və Qızılgül Buketi","en":"Pink Hydrangea & Rose Bouquet","ru":"Букет розовых гортензий и роз"}'::jsonb, '{"az":"Çəhrayı hortenziya və qızılgüllərdən yumşaq tonlu həcmli buket.","en":"A soft, voluminous bouquet of pink hydrangeas and roses.","ru":"Нежный объёмный букет из розовых гортензий и роз."}'::jsonb, 'bouquets', 'pink', '/assets/products/cehrayi-hortenziya-qizilgul-buketi.webp', false, -86),
  ('{"az":"Ayıcıqlı Hörmə Gül Səbəti","en":"Woven Flower Basket with Teddy Bear","ru":"Цветочная корзина с плюшевым мишкой"}'::jsonb, '{"az":"Böyük boz ayıcıq və qarışıq güllərlə dolu hörmə səbət.","en":"A woven basket of mixed flowers with a large grey teddy bear.","ru":"Плетёная корзина со смешанными цветами и большим серым мишкой."}'::jsonb, 'baskets', 'all', '/assets/products/ayicikli-qarisiq-gul-sebeti.webp', true, -85),
  ('{"az":"Böyük Qırmızı Qızılgül Buketi","en":"Grand Red Rose Bouquet","ru":"Большой букет красных роз"}'::jsonb, '{"az":"Ağ bükülüdə, evkalipt ilə tamamlanmış böyük qırmızı qızılgül buketi.","en":"A large red rose bouquet with eucalyptus in white wrapping.","ru":"Большой букет красных роз с эвкалиптом в белой упаковке."}'::jsonb, 'roses', 'red', '/assets/products/boyuk-qirmizi-qizilgul-evkalipt-buketi.webp', true, -84),
  ('{"az":"Qara Qutuda Qırmızı Qızılgüllər","en":"Red Roses in a Black Box","ru":"Красные розы в чёрной коробке"}'::jsonb, '{"az":"Qara dairəvi qutuda evkaliptlə qırmızı qızılgül kompozisiyası.","en":"Red roses and eucalyptus arranged in a round black box.","ru":"Красные розы с эвкалиптом в круглой чёрной коробке."}'::jsonb, 'boxes', 'red', '/assets/products/qirmizi-qizilgul-evkalipt-qara-qutuda.webp', false, -83),
  ('{"az":"Qırmızı Qutuda Qırmızı Kompozisiya","en":"All-Red Box Arrangement","ru":"Красная композиция в красной коробке"}'::jsonb, '{"az":"Uzun lentləri olan qırmızı dairəvi qutuda tamamilə qırmızı kompozisiya.","en":"An entirely red arrangement in a round red box with long ribbons.","ru":"Полностью красная композиция в круглой красной коробке с длинными лентами."}'::jsonb, 'boxes', 'red', '/assets/products/qirmizi-qutuda-qirmizi-gul-kompozisiyasi.webp', true, -82),
  ('{"az":"Mirvari Bəzəkli Sarı-Mavi Səbət","en":"Yellow & Blue Pearl-Trim Basket","ru":"Жёлто-голубая корзина с жемчугом"}'::jsonb, '{"az":"Mirvari sapları ilə bəzədilmiş səbətdə sarı və mavi çiçəklər.","en":"Yellow and blue blooms in a basket draped with pearl strands.","ru":"Жёлтые и голубые цветы в корзине, украшенной нитями жемчуга."}'::jsonb, 'baskets', 'yellow', '/assets/products/sari-mavi-gul-mirvari-sebet-kompozisiyasi.webp', false, -81),
  ('{"az":"Ağ Anturium və Mirvari Kompozisiyası","en":"White Anthurium & Pearl Arrangement","ru":"Композиция с белым антуриумом и жемчугом"}'::jsonb, '{"az":"Ağ çiçəklər, anturium və mirvari sapları ilə heykəlvari eksklyuziv kompozisiya.","en":"A sculptural arrangement of white blooms, anthurium and pearl strands.","ru":"Скульптурная композиция из белых цветов, антуриума и нитей жемчуга."}'::jsonb, 'exclusive', 'white', '/assets/products/ag-anturium-mirvari-eksklyuziv-kompozisiya.webp', true, -80),
  ('{"az":"Pastel Çəhrayı Hörmə Səbət","en":"Pastel Pink Woven Basket","ru":"Пастельная розовая плетёная корзина"}'::jsonb, '{"az":"Ağ hörmə səbətdə pastel çəhrayı güllər və evkalipt.","en":"Pastel pink blooms and eucalyptus in a white woven basket.","ru":"Пастельно-розовые цветы и эвкалипт в белой плетёной корзине."}'::jsonb, 'baskets', 'pink', '/assets/products/pastel-cehrayi-hasir-sebet-kompozisiyasi.webp', false, -79),
  ('{"az":"Balqabaqda Payız Kompozisiyası","en":"Autumn Arrangement in a Pumpkin","ru":"Осенняя композиция в тыкве"}'::jsonb, '{"az":"Balqabağın içində günəbaxan və payız tonlu çiçəklərdən kompozisiya.","en":"Sunflowers and autumn-toned blooms arranged inside a pumpkin.","ru":"Подсолнухи и цветы осенних оттенков в тыкве."}'::jsonb, 'exclusive', 'orange', '/assets/products/balqabaqda-gunebaxan-payiz-kompozisiyasi.webp', false, -78),
  ('{"az":"Payız Tonlu Pudra Qızılgül Buketi","en":"Autumn-Toned Powder Rose Bouquet","ru":"Осенний букет с пудровыми розами"}'::jsonb, '{"az":"Pudra rəngli qızılgüllər və narıncı payız budaqları ilə böyük buket.","en":"A large bouquet of powder-toned roses with orange autumn branches.","ru":"Большой букет пудровых роз с оранжевыми осенними ветками."}'::jsonb, 'exclusive', 'orange', '/assets/products/payiz-tonlu-pudra-qizilgul-boyuk-buket.webp', false, -77),
  ('{"az":"Krem-Şaftalı Qızılgül Buketi","en":"Cream & Peach Rose Bouquet","ru":"Кремово-персиковый букет роз"}'::jsonb, '{"az":"Şəffaf bükülüdə krem və şaftalı tonlu qızılgüllər.","en":"Cream and peach-toned roses in sheer wrapping.","ru":"Кремовые и персиковые розы в прозрачной упаковке."}'::jsonb, 'bouquets', 'orange', '/assets/products/krem-saftali-qizilgul-buketi.webp', false, -76),
  ('{"az":"Terrakota Payız Buketi","en":"Terracotta Autumn Bouquet","ru":"Терракотовый осенний букет"}'::jsonb, '{"az":"Narıncı və terrakota tonlarında çiçəklər və payız yarpaqları ilə buket.","en":"Orange and terracotta blooms with autumn leaves.","ru":"Цветы оранжевых и терракотовых оттенков с осенней листвой."}'::jsonb, 'bouquets', 'orange', '/assets/products/narinci-terrakota-payiz-buketi.webp', false, -75),
  ('{"az":"Hündür Payız Kompozisiyası","en":"Tall Autumn Arrangement","ru":"Высокая осенняя композиция"}'::jsonb, '{"az":"Yaşıl hortenziya, anturium və payız budaqları ilə hündür kompozisiya.","en":"A tall arrangement of green hydrangeas, anthurium and autumn branches.","ru":"Высокая композиция с зелёными гортензиями, антуриумом и осенними ветками."}'::jsonb, 'exclusive', 'orange', '/assets/products/hundur-payiz-hortenziya-anturium-kompozisiyasi.webp', false, -74),
  ('{"az":"Narıncı Balqabaq Kompozisiyası","en":"Orange Pumpkin Arrangement","ru":"Оранжевая композиция в тыкве"}'::jsonb, '{"az":"Balqabaq üzərində narıncı və tünd çəhrayı çiçəklərlə payız kompozisiyası.","en":"An autumn arrangement of orange and deep pink blooms in a pumpkin.","ru":"Осенняя композиция в тыкве с оранжевыми и тёмно-розовыми цветами."}'::jsonb, 'exclusive', 'orange', '/assets/products/balqabaq-narinci-gul-payiz-kompozisiyasi.webp', false, -73),
  ('{"az":"Bənövşəyi Xrizantema Buketi","en":"Purple Chrysanthemum Bouquet","ru":"Букет фиолетовых хризантем"}'::jsonb, '{"az":"Yasəmən rəngli bükülüdə, bənövşəyi tonlarda xrizantemalar.","en":"Purple-toned chrysanthemums in lilac wrapping.","ru":"Хризантемы фиолетовых оттенков в сиреневой упаковке."}'::jsonb, 'bouquets', 'purple', '/assets/products/benovseyi-xrizantema-buketi.webp', false, -72),
  ('{"az":"Qara Bükülüdə Qırmızı Qızılgüllər","en":"Red Roses in Black Wrap","ru":"Красные розы в чёрной упаковке"}'::jsonb, '{"az":"Qara bükülüdə, qırmızı lentli klassik qırmızı qızılgül buketi.","en":"A classic red rose bouquet in black wrapping with a red ribbon.","ru":"Классический букет красных роз в чёрной упаковке с красной лентой."}'::jsonb, 'roses', 'red', '/assets/products/qara-qablasdirmada-qirmizi-qizilgul-buketi.webp', false, -71),
  ('{"az":"Mərcan Çəhrayı Qarışıq Buket","en":"Coral & Pink Mixed Bouquet","ru":"Коралловый смешанный букет"}'::jsonb, '{"az":"Ağ bükülüdə mərcan və çəhrayı tonlarda qarışıq çiçəklər.","en":"Coral and pink mixed blooms in white wrapping.","ru":"Смешанные цветы кораллового и розового оттенков в белой упаковке."}'::jsonb, 'bouquets', 'pink', '/assets/products/cehrayi-marcan-gul-buketi.webp', true, -70),
  ('{"az":"Ağ Qutuda Rəngarəng Kompozisiya","en":"Colourful Arrangement in a White Box","ru":"Яркая композиция в белой коробке"}'::jsonb, '{"az":"Bənövşəyi lentli ağ dairəvi qutuda rəngarəng qarışıq çiçəklər.","en":"Colourful mixed blooms in a round white box with a purple ribbon.","ru":"Яркие смешанные цветы в круглой белой коробке с фиолетовой лентой."}'::jsonb, 'boxes', 'purple', '/assets/products/ag-qutuda-rengareng-qarisiq-gul-kompozisiyasi.webp', false, -69)
) as v(name, description, category_id, color, image_url, featured, sort_order)
where not exists (select 1 from public.products p where p.image_url = v.image_url);
commit;
